import { useState } from 'react';
import axios from 'axios';

const BlogForm = () => {
  const [title, setTitle] = useState('');
  const [content, setContent] = useState('');
  const [author, setAuthor] = useState('');
  const [category, setCategory] = useState('');

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      await axios.post('http://localhost:8080/api/blogs', { title, content, author, category });
      window.location.reload();
    } catch (error) {
      console.error('Error creating blog:', error);
    }
  };

  return (
    <form onSubmit={handleSubmit} className="mb-4">
      <input type="text" placeholder="Title" value={title} onChange={(e) => setTitle(e.target.value)} required className="border p-2 w-full mb-2" />
      <textarea placeholder="Content" value={content} onChange={(e) => setContent(e.target.value)} required className="border p-2 w-full mb-2" />
      <input type="text" placeholder="Author" value={author} onChange={(e) => setAuthor(e.target.value)} required className="border p-2 w-full mb-2" />
      <input type="text" placeholder="Category" value={category} onChange={(e) => setCategory(e.target.value)} required className="border p-2 w-full mb-2" />
      <button type="submit" className="bg-blue-500 text-white p-2 w-full">Create Blog</button>
    </form>
  );
};

export default BlogForm;
